const init = $('Initialize Parameters').first().json;
const project = $('Load Project').first().json;
const pmJob = $('Get Latest PM Job').first().json;
const job = $json;
return [{ json: { projectId: project.id, projectSlug: project.slug, projectName: project.name || project.slug, jobId: job.id, inputJobId: pmJob?.id || null } }];

const ctx = $('Pass Context').first().json;
const rows = $input.all().map(i => i.json);
const byType = {};
for (const r of rows) byType[r.type] = r.content;

const prdMd = byType.prd_md?.markdown || '';
const brd = byType.brd || {};

if (!prdMd) throw new Error('Missing PRD artifact for project ' + ctx.projectSlug);

return [{ json: { ...ctx, prdMarkdown: prdMd, brd } }];

const ctx = $json;
const projectSlug = ctx.projectSlug;
const jobId = ctx.jobId;

const repoDir = '/opt/workspace/software-delivery';
const projectDir = repoDir + '/' + projectSlug + '-docs';
const remote = 'git@github.com:shlapolosa/software-delivery.git';

let sh = 'set -e\n';
sh += 'mkdir -p /opt/workspace\n';
sh += "if [ ! -d '" + repoDir + "/.git' ]; then git clone '" + remote + "' '" + repoDir + "'; fi\n";
sh += "cd '" + repoDir + "'\n";
sh += "git remote set-url origin '" + remote + "'\n";
sh += 'git fetch origin\n';
sh += "git checkout -B '" + projectSlug + "' 'origin/" + projectSlug + "' 2>/dev/null || git checkout -B '" + projectSlug + "'\n";
sh += "mkdir -p '" + projectDir + "/docs'\n";

// Write PRD.md if needed
sh += "cat > '" + projectDir + "/docs/PRD.md' <<'EOF_" + jobId + "'\n";
sh += ctx.prdMarkdown + "\nEOF_" + jobId + "\n";

sh += "git add '" + projectSlug + "-docs/docs/PRD.md'\n";
sh += "git commit -m 'Update PRD for " + projectSlug + " (job " + jobId + ")' || true\n";
sh += "git push -u origin '" + projectSlug + "'\n";

return [{ json: { ...ctx, gitScript: sh } }];

const ctx = $('Pass Context').first().json;
const projectSlug = ctx.projectSlug;
const jobId = ctx.jobId;

const remote = 'git@github.com:shlapolosa/software-delivery.git';
const repoDirHost = '/opt/workspace/software-delivery';
const repoDirHostForContainer = '/local-ai-packaged/projects/software-delivery';
const projectDirHostForContainer = repoDirHostForContainer + '/' + projectSlug + '-docs';
const projectDirContainer = '/app/projects/software-delivery/' + projectSlug + '-docs';

let sh = 'set -e\n';
sh += "if [ ! -d '" + repoDirHost + "/.git' ]; then git clone '" + remote + "' '" + repoDirHost + "'; fi\n";
sh += "cd '" + repoDirHost + "'\n";
sh += "git remote set-url origin '" + remote + "'\n";
sh += 'git fetch origin\n';
sh += "git checkout '" + projectSlug + "'\n";

sh += "mkdir -p '" + repoDirHostForContainer + "'\n";
sh += "if command -v rsync >/dev/null 2>&1; then rsync -a --delete '" + repoDirHost + "/' '" + repoDirHostForContainer + "/'; else cp -a '" + repoDirHost + "/.' '" + repoDirHostForContainer + "/'; fi\n";

sh += "test -f '" + projectDirHostForContainer + "/docs/PRD.md'\n";
sh += "docker exec -w '" + projectDirContainer + "' taskmaster task-master init -y || true\n";
sh += "docker exec -w '" + projectDirContainer + "' taskmaster task-master parse-prd --input='docs/PRD.md' --num-tasks=15\n";
sh += "for i in 1 2 3 4 5; do docker exec -w '" + projectDirContainer + "' taskmaster task-master analyze-complexity || true; docker exec -w '" + projectDirContainer + "' taskmaster task-master expand --all --force || break; done\n";
sh += "docker exec -w '" + projectDirContainer + "' taskmaster task-master analyze-complexity || true\n";

sh += "mkdir -p '" + projectDirHostForContainer + "/backlog'\n";
sh += "TASKS_JSON='" + projectDirHostForContainer + "/.taskmaster/tasks/tasks.json'\n";
sh += "if [ -f \"$TASKS_JSON\" ]; then cp \"$TASKS_JSON\" '" + projectDirHostForContainer + "/backlog/tasks.json'; fi\n";

sh += "cd '" + repoDirHostForContainer + "'\n";
sh += "git remote set-url origin '" + remote + "'\n";
sh += "git checkout '" + projectSlug + "'\n";
sh += "git add '" + projectSlug + "-docs/backlog/tasks.json' || true\n";
sh += "git commit -m 'Add taskmaster tasks for " + projectSlug + " (job " + jobId + ")' || true\n";
sh += "git push origin '" + projectSlug + "'\n";

return [{ json: { ...ctx, taskmasterScript: sh } }];
